import java.util.*;

class Solution {
    public int minSpeedOnTime(int[] dist, double hour) {
        final int MAX = 10000000;
        if (!onTime(dist, hour, MAX)) return -1;  // even the fastest speed fails
        int lo = 1, hi = MAX;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (onTime(dist, hour, mid)) hi = mid; // fast enough, try slower
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean onTime(int[] dist, double hour, int s) {
        long whole = 0;
        for (int i = 0; i < dist.length - 1; i++) whole += (dist[i] + (long) s - 1) / s; // wait for the next hour
        double total = whole + (double) dist[dist.length - 1] / s;                     // last ride: no waiting
        return total <= hour + 1e-9;
    }
}

