    def minSpeedOnTime(self, dist: List[int], hour: float) -> int:
        H = round(hour * 100)
        def ok(s):
            t = sum((d + s - 1) // s for d in dist[:-1])
            return 100 * (t * s + dist[-1]) <= H * s
        lo, hi = 1, 10 ** 7
        if not ok(hi): return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid): hi = mid
            else: lo = mid + 1
        return lo

