function minSpeedOnTime(dist, hour) {
  const n = dist.length;
  const time = (s) => { let t = 0; for (let i = 0; i < n - 1; i++) t += Math.ceil(dist[i] / s); return t + dist[n - 1] / s; };
  const ok = (s) => time(s) <= hour + 1e-9;
  let lo = 1, hi = 1e7;
  if (!ok(hi)) return -1;
  while (lo < hi) { const m = Math.floor((lo + hi) / 2); if (ok(m)) hi = m; else lo = m + 1; }
  return lo;
}
